{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Ofloxacin absolute oral bioavailability was >95% in healthy volunteers at 200 mg oral versus IV, directly supporting high bioavailability."
    },
    {
      "card_ids": ["C04"],
      "claim": "Emtricitabine absolute oral bioavailability was 93% in humans, directly supporting high bioavailability."
    },
    {
      "card_ids": ["C24"],
      "claim": "Sildenafil absolute oral bioavailability was 41% (range 25-63%) in human subjects, still well above the 20% threshold and supporting high bioavailability."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All ten evidence molecules support high oral bioavailability; absolute F values range from about 30-54% to >95%, all above the 20% threshold. Inconsistent records and low pediatric values were discounted as provenance conflicts or non-ordinary conditions.",
  "evidence_gaps": [
    "Molecule 1 contains a levofloxacin record (C67) under the ofloxacin group; provenance conflict, discounted.",
    "Molecule 8 contains didanosine records (C47, C45) under the emtricitabine group; provenance conflict, discounted.",
    "Molecule 6 has pediatric didanosine records below 20% (C76, C08) that conflict with adult absolute values; adult absolute values support high.",
    "Molecule 2 has one low RBA record (C01) conflicting with multiple absolute measurements; discounted as non-absolute."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C05", "C04", "C24"],
  "revision_action": "initial",
  "supportive_card_ids": ["C05", "C04", "C24"]
}

